  QkObsTerm term = {coeff, 3, bit_terms, indices, num_qubits};
  qk_obs_add_term(obs, &term);

  size_t num_terms = qk_obs_num_terms(obs);
  size_t *boundaries = qk_obs_boundaries(obs);

  for (size_t i = 0; i < num_terms + 1; i++) {
